        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def is_num(x):
        return isinstance(x, (int, float))

    def first_pos(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            for kx, ky in (("x", "y"), ("row", "col"), ("r", "c")):
                if kx in obj and ky in obj and is_num(obj.get(kx)) and is_num(obj.get(ky)):
                    return [int(obj.get(kx)), int(obj.get(ky))]
        if isinstance(obj, (list, tuple)):
            if len(obj) >= 2 and is_num(obj[0]) and is_num(obj[1]):
                return [int(obj[0]), int(obj[1])]
        return None

    def extract_positions(value):
        out = []
        if value is None:
            return out
        if isinstance(value, dict):
            for k in ("positions", "items", "targets", "resources", "enemies", "opponents", "agents", "players", "cells", "points", "territory", "frontier"):
                if k in value:
                    out.extend(extract_positions(value.get(k)))
            p = first_pos(value)
            if p is not None:
                out.append(p)
            return out
