            if len(value) == 2 and is_num(value[0]) and is_num(value[1]):
                out.append([int(value[0]), int(value[1])])
                return out
            for item in value:
                out.extend(extract_positions(item))
        return out

    def get_me(obs):
        for k in ("self", "me", "agent", "player", "unit", "avatar"):
            v = obs.get(k)
            p = first_pos(v)
            if p is not None:
                return p
        for k in ("position", "pos", "loc", "location", "coord", "coordinates"):
            v = obs.get(k)
            p = first_pos(v)
            if p is not None:
                return p
        return [0, 0]

    def get_grid(obs):
        for k in ("grid", "board", "map", "world", "terrain"):
            g = obs.get(k)
            if isinstance(g, (list, tuple)) and g:
                return g
        return None

    def in_bounds(x, y, grid):
        if grid is None:
            return True
        h = len(grid)
        if h <= 0:
            return True
        w = None
        try:
            w = len(grid[0])
        except Exception:
            w = None
        if w is None or w <= 0:
            return True
        return 0 <= x < w and 0 <= y < h

    def blocked(x, y, grid):
        if not in_bounds(x, y, grid):
            return True
        if grid is None:
            return False
        try:
            cell = grid[y][x]
        except Exception:
            return False
        if isinstance(cell, str):
            return cell in ("#", "X", "x", "W", "w", "A")
        if isinstance(cell, (int, float)):
            return cell in (-1, 9, 99)
        if isinstance(cell, dict):
            for kk in ("wall", "blocked", "occupied", "obstacle"):
                if cell.get(kk):
                    return True
        return False

