                d0e = dist(me, nearest_enemy)
                d1e = dist([nx, ny], nearest_enemy)
                score += (d1e - d0e) * 4

        elif mode == "pursuit":
            # Chase if close enough, otherwise keep distance from stronger-looking threats if any.
            if nearest_enemy is not None:
                d0e = dist(me, nearest_enemy)
                d1e = dist([nx, ny], nearest_enemy)
                score += (d0e - d1e) * 12
            # slight bias to not stand still
            if dx == 0 and dy == 0:
                score -= 1

        elif mode == "territory":
