            if nearest_goal is not None:
                score += 2
            if nearest_enemy is not None:
                d0e = dist(me, nearest_enemy)
                d1e = dist([nx, ny], nearest_enemy)
                score += (d1e - d0e) * 2
            # prefer moves that change position
            if dx != 0 or dy != 0:
                score += 1

        else:
            # Generic exploration: move toward any known point, else wander deterministically.
            if goals:
                score += 5
            else:
                score += (nx + ny) % 3

        # Mild anti-stall / edge preference
        if dx == 0 and dy == 0:
            score -= 2
        if grid is not None:
            if not in_bounds(nx, ny, grid):
                score -= 1000

        if score > best_score:
            best_score = score
            best = (dx, dy)

    dx, dy = best
    dx = clamp(dx)
    dy = clamp(dy)
    return [dx, dy]

